-- ==========================================================================
-- VYBE PRODUCTION SEED DATA FOR SUPABASE POSTGRESQL
-- Idempotent SQL Seed: Inserts demo accounts, companies, & 45 travel packages
-- ==========================================================================
BEGIN;

-- 1. DEMO USERS
SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));

-- 2. TRAVELER PROFILES
SELECT setval('traveler_profiles_id_seq', (SELECT MAX(id) FROM traveler_profiles));

-- 3. TRAVEL COMPANIES
SELECT setval('travel_companies_id_seq', (SELECT MAX(id) FROM travel_companies));

-- 4. TRAVEL PACKAGES (45 Curated Experiences)
SELECT setval('travel_packages_id_seq', (SELECT MAX(id) FROM travel_packages));

COMMIT;